-- Read-only validation for COMPANY_CUSTOMER_EMAIL_TEMPLATES.sql.
select
  to_regclass('public.company_customer_email_settings') is not null as settings_table_exists,
  to_regclass('public.company_customer_email_revisions') is not null as revisions_table_exists,
  coalesce((select relrowsecurity from pg_catalog.pg_class where oid=to_regclass('public.company_customer_email_settings')),false) as rls_enabled,
  coalesce((select relrowsecurity from pg_catalog.pg_class where oid=to_regclass('public.company_customer_email_revisions')),false) as revisions_rls_enabled,
  case when to_regclass('public.company_customer_email_settings') is null then false else not has_table_privilege('authenticated','public.company_customer_email_settings','select') end as authenticated_direct_select_denied,
  case when to_regclass('public.company_customer_email_revisions') is null then false else not has_table_privilege('authenticated','public.company_customer_email_revisions','select') end as authenticated_history_select_denied,
  coalesce(case when to_regprocedure('public.get_company_customer_email_settings(uuid)') is null then false else has_function_privilege('authenticated',to_regprocedure('public.get_company_customer_email_settings(uuid)'),'execute') end,false) as settings_read_rpc_granted,
  coalesce(case when to_regprocedure('public.save_company_customer_email_settings(uuid,jsonb)') is null then false else has_function_privilege('authenticated',to_regprocedure('public.save_company_customer_email_settings(uuid,jsonb)'),'execute') end,false) as settings_write_rpc_granted,
  coalesce(case when to_regprocedure('public.get_company_customer_email_revisions(uuid)') is null then false else has_function_privilege('authenticated',to_regprocedure('public.get_company_customer_email_revisions(uuid)'),'execute') end,false) as revision_read_rpc_granted,
  coalesce(case when to_regprocedure('public.restore_company_customer_email_revision(uuid,uuid)') is null then false else has_function_privilege('authenticated',to_regprocedure('public.restore_company_customer_email_revision(uuid,uuid)'),'execute') end,false) as revision_restore_rpc_granted,
  coalesce(case when to_regprocedure('public.get_company_customer_email_settings(uuid)') is null then false else not has_function_privilege('anon',to_regprocedure('public.get_company_customer_email_settings(uuid)'),'execute') end,false) as anonymous_settings_read_denied,
  coalesce(case when to_regprocedure('public.save_company_customer_email_settings(uuid,jsonb)') is null then false else not has_function_privilege('anon',to_regprocedure('public.save_company_customer_email_settings(uuid,jsonb)'),'execute') end,false) as anonymous_settings_write_denied,
  coalesce(case when to_regprocedure('public.get_company_customer_email_template(uuid,text,text,uuid)') is null then false else has_function_privilege('service_role',to_regprocedure('public.get_company_customer_email_template(uuid,text,text,uuid)'),'execute') end,false) as worker_template_rpc_granted,
  coalesce(case when to_regprocedure('public.get_company_customer_email_template(uuid,text,text,uuid)') is null then false else has_function_privilege('authenticated',to_regprocedure('public.get_company_customer_email_template(uuid,text,text,uuid)'),'execute') end,false) as authenticated_template_rpc_granted,
  to_regprocedure('public.default_company_customer_email_settings()') is not null as default_settings_function_exists,
  to_regprocedure('public.validate_company_customer_email_settings(jsonb)') is not null as validation_function_exists,
  to_regprocedure('public.get_company_customer_email_revisions(uuid)') is not null as revision_read_function_exists,
  to_regprocedure('public.restore_company_customer_email_revision(uuid,uuid)') is not null as revision_restore_function_exists;
